const require_index = require("../useEventListener/index.js");
let react = require("react");
//#region src/useHover/index.ts
const useHover = (target) => {
	const [hovered, setHovered] = (0, react.useState)(false);
	const onMouseEnter = (0, react.useCallback)(() => setHovered(true), []);
	const onMouseLeave = (0, react.useCallback)(() => setHovered(false), []);
	require_index.useEventListener("mouseenter", onMouseEnter, target);
	require_index.useEventListener("mouseleave", onMouseLeave, target);
	return hovered;
};
//#endregion
exports.useHover = useHover;
